sp_widget.client_script:
api.controller = function($scope) {

  /* =========================================================
     GATENOW · MY APPLICATIONS · Client script

     Tabs, search and paging run against the list already in
     memory. No writes on this page, so nothing goes back to
     the server.
     ========================================================= */

  var c = this;

  c.query = '';
  c.tab   = 'all';
  c.page  = 1;

  var PER_PAGE = c.data.pageSize || 10;

  /* the record showing in the modal, or null */
  c.open = null;

  c.tabs = [
    { key: 'all',     label: c.data.t.tabAll },
    { key: 'new',     label: c.data.t.tabNew },
    { key: 'review',  label: c.data.t.tabReview },
    { key: 'awarded', label: c.data.t.tabAwarded },
    { key: 'closed',  label: c.data.t.tabClosed }
  ];

  function hit(a, q) {
    return (
      (a.program || '').toLowerCase().indexOf(q) !== -1 ||
      (a.number  || '').toLowerCase().indexOf(q) !== -1 ||
      (a.title   || '').toLowerCase().indexOf(q) !== -1
    );
  }

  function matching() {
    var q = (c.query || '').trim().toLowerCase();

    var out = (c.data.applications || []).filter(function(a) {
      if (c.tab !== 'all' && a.group !== c.tab) return false;
      if (q && !hit(a, q)) return false;
      return true;
    });

    return out;
  }

  c.total     = function() { return matching().length; };
  c.pageCount = function() { return Math.max(1, Math.ceil(matching().length / PER_PAGE)); };

  c.shown = function() {
    var start = (c.page - 1) * PER_PAGE;
    return matching().slice(start, start + PER_PAGE);
  };

  function reset() { c.page = 1; }

  c.onChange = function() { reset(); };

  c.setTab = function(key) {
    if (c.tab === key) return;
    c.tab = key;
    reset();
  };

  c.clearSearch = function() { c.query = ''; reset(); };

  c.clearAll = function() {
    c.query = '';
    c.tab = 'all';
    reset();
  };


  /* =====================================================
     DETAIL

     The whole record is already on the page, so opening the
     modal is a local assignment. Fetching it on open would mean
     a server call, and a server call repaints the widget.
     ===================================================== */

  c.openDetail = function(application) {
    c.open = application || null;
  };

  c.closeDetail = function() {
    c.open = null;
  };

  /* escape closes it, which people expect and nobody documents */
  $scope.$on('keydown', function(e, event) {
    if (event && event.keyCode === 27) c.closeDetail();
  });


  /* =====================================================
     PAGING
     ===================================================== */

  c.goto = function(n) {
    if (n === '...') return;
    if (n < 1 || n > c.pageCount() || n === c.page) return;
    c.page = n;
  };

  c.prev = function() { c.goto(c.page - 1); };
  c.next = function() { c.goto(c.page + 1); };

  /* first and last always reachable, current page keeps a
     neighbour either side, gaps collapse to an ellipsis */
  c.pages = function() {
    var n = c.pageCount();
    var p = c.page;
    var out = [];

    if (n <= 7) {
      for (var i = 1; i <= n; i++) out.push(i);
      return out;
    }

    out.push(1);

    var from = Math.max(2, p - 1);
    var to   = Math.min(n - 1, p + 1);

    if (p <= 3) to = 4;
    if (p >= n - 2) from = n - 3;

    if (from > 2) out.push('...');
    for (var j = from; j <= to; j++) out.push(j);
    if (to < n - 1) out.push('...');

    out.push(n);
    return out;
  };

}

sp_widget.css:
/* =========================================================
   GATENOW · MY APPLICATIONS
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   WHAT CHANGED FROM THE VERSION ON SCREEN

   Colour. The indigo on the bars, the active tab and the avatar
   was a fifth hue that belonged to no system. Everything is now
   the logo blue for the one accent, and every neutral is the
   same navy at a different opacity. Green for awarded, amber for
   attention, and nothing else.

   Type. Headings were heavier and larger than they needed to be
   against the data. The figures now carry the weight, the
   headings step back, and every amount and date uses tabular
   figures so the columns line up down the table.

   Radius and shadow. 16px on the panels, a one pixel hairline
   and a very light shadow, matching the funding programs page.

   TYPE
     tile      30  700  tabular   the four figures
     title     26  700  -0.03em   page title
     panel     15  600  -0.014em  panel headings
     name      14  600             program name in a row
     data      14  600  tabular    amounts and dates
     label     11  600   0.14em    uppercase small caps
   ========================================================= */

/* ---------- overflow overrides ----------
   Service Portal wraps every widget in a panel that clips
   anything leaving its box, which cuts off the sidebar tooltips.
   ------------------------------------------------------- */

.panel,
.panel-body,
.sp-widget { overflow: visible !important; }

.gn-layout { overflow: visible !important; }

/* The column holds the rail and lets it decide how wide to be.
   It used to carry a width through an inline ng-style, which is
   what put 140px of the rail on top of this page: the column
   reserved 96 while the rail draws 236.

   The transition moved to the rail, which is the element that
   actually changes width. Animating a wrapper that never
   resized was doing nothing. */

.aw-sidebar {
  flex: 0 0 auto;
  position: sticky;
  top: 0;
  height: 100vh;
  z-index: 10; /* Ensures sidebar tooltips stay above the scrolling dashboard */
  overflow: visible; /* Kept visible to prevent tooltip clipping as noted in your comments */
}


/* ---------- typeface ---------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- ink ---------- */
$p-navy:   #0a2540;
$p-ink-2:  rgba(10, 37, 64, 0.72);
$p-ink-3:  rgba(10, 37, 64, 0.54);
$p-ink-4:  rgba(10, 37, 64, 0.38);
$p-line:   rgba(10, 37, 64, 0.10);
$p-line-2: rgba(10, 37, 64, 0.06);
$p-tint:   rgba(10, 37, 64, 0.03);

/* ---------- accent ---------- */
$p-blue:    #1560e0;
$p-blue-dk: #0f4cbb;
$p-blue-1:  rgba(21, 96, 224, 0.08);
$p-blue-2:  rgba(21, 96, 224, 0.16);

/* ---------- state ---------- */
$p-good:   #1f8a63;
$p-good-1: rgba(31, 138, 99, 0.12);
$p-warn:   #a4741f;
$p-warn-1: rgba(164, 116, 31, 0.10);

$p-white: #ffffff;
$p-page:  #f4f6fb;
$p-ease:  cubic-bezier(0.45, 0.05, 0.25, 1);

$p-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   PAGE
   ========================================================= */

.gn-layout {
  display: flex;
  align-items: stretch;
  min-height: 100vh;
  background: $p-page;
  font-family: $p-font;
}

/* Without min-width: 0 a flex child refuses to shrink below its
   own content width, and slides under the rail rather than
   narrowing. That is the usual cause of a stubborn overlap once
   the widths are right. */
.gap {
  flex: 1;
  min-width: 0;
  overflow: visible;
}

.gap {
  min-height: 100vh;
  padding: 28px 36px 68px;
  background: $p-page;
  font-family: $p-font;
  color: $p-navy;
  -webkit-font-smoothing: antialiased;
}

.gap *,
.gap *::before,
.gap *::after { box-sizing: border-box; }

.gap-right { text-align: right; }


/* =========================================================
   HEADER
   ========================================================= */

.gap-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px 24px;
  margin-bottom: 22px;
}

.gap-top__lead { min-width: 0; }

.gap .gap-top__title {
  margin: 0;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: $p-navy;
}

.gap .gap-top__sub {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 7px 0 0;
  font-size: 13.5px;
  color: $p-ink-3;
}

.gap-live {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: $p-good;
  box-shadow: 0 0 0 3px $p-good-1;
  flex-shrink: 0;
}

.gap-top__right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.gap-search {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 340px;
  height: 42px;
  padding: 0 12px 0 14px;
  margin: 0;
  border: 1px solid $p-line;
  border-radius: 11px;
  background: $p-white;
  font-weight: 400;
  transition: border-color 0.4s $p-ease, box-shadow 0.4s $p-ease;
}

.gap-search:focus-within {
  border-color: rgba(21, 96, 224, 0.45);
  box-shadow: 0 0 0 3px $p-blue-1;
}

.gap-search__icon {
  font-size: 13px;
  color: $p-ink-4;
  flex-shrink: 0;
}

.gap-search__field {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  font-family: inherit;
  font-size: 14px;
  color: $p-navy;
}

.gap-search__field::placeholder { color: $p-ink-4; }

.gap-search__clear {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: $p-tint;
  color: $p-ink-3;
  font-size: 10px;
  cursor: pointer;
  flex-shrink: 0;
}

/* the accent blue. Navy read as a dark chip beside a white
   search field, and the initials are a person, not a state. */
.gap-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: $p-blue;
  box-shadow: 0 6px 16px rgba(21, 96, 224, 0.28);
  color: $p-white;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.03em;
  flex-shrink: 0;
}


/* =========================================================
   FIGURES
   ========================================================= */

.gap-tiles {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 16px;
}

.gap-tile {
  position: relative;
  padding: 20px 22px 22px;
  border: 1px solid $p-line;
  border-radius: 16px;
  background: $p-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
  transition: transform 0.5s $p-ease, box-shadow 0.5s $p-ease;
}

.gap-tile:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 32px rgba(10, 37, 64, 0.08);
}

.gap-tile__rule {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 2px;
  background: $p-blue-2;
  transform-origin: left center;
}

.gap .gap-tile__label {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $p-ink-4;
}

/* the figure carries the weight, not the heading above it */
.gap .gap-tile__value {
  margin: 12px 0 0;
  font-size: 30px;
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.034em;
  font-variant-numeric: tabular-nums;
  color: $p-navy;
}

.gap .gap-tile__note {
  margin: 8px 0 0;
  font-size: 12.5px;
  line-height: 1.5;
  color: $p-ink-3;
}


/* =========================================================
   PANELS
   ========================================================= */

.gap-panels {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
  gap: 16px;
  margin-bottom: 16px;
}

.gap-panel {
  display: flex;
  flex-direction: column;
  padding: 22px 24px 24px;
  border: 1px solid $p-line;
  border-radius: 16px;
  background: $p-white;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
}

.gap-panel__head { margin-bottom: 20px; }

.gap .gap-panel__title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.014em;
  color: $p-navy;
}

.gap .gap-panel__hint {
  margin: 5px 0 0;
  font-size: 12.5px;
  color: $p-ink-4;
}

.gap .gap-panel__foot {
  margin: 18px 0 0;
  padding-top: 14px;
  border-top: 1px solid $p-line-2;
  font-size: 12px;
  line-height: 1.55;
  color: $p-ink-4;
}

.gap .gap-panel__empty {
  margin: 0;
  padding: 26px 0 6px;
  font-size: 13.5px;
  color: $p-ink-4;
}


/* ---------- stage conversion ---------- */

.gap-funnel {
  display: grid;
  gap: 14px;
}

.gap-fun {
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr) 46px;
  align-items: center;
  gap: 16px;
}

.gap-fun__label {
  font-size: 13.5px;
  font-weight: 500;
  color: $p-ink-2;
}

.gap-fun__track {
  height: 30px;
  border-radius: 8px;
  background: $p-tint;
  overflow: hidden;
}

.gap-fun__fill {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  height: 100%;
  min-width: 0;
  padding: 0 11px;
  border-radius: 8px;
  background: $p-blue;
  transform-origin: left center;
}

/* declined is the one row where blue would be the wrong story */
.gap-fun--declined .gap-fun__fill { background: rgba(10, 37, 64, 0.3); }
.gap-fun--awarded .gap-fun__fill  { background: $p-good; }

.gap-fun__count {
  font-size: 13px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $p-white;
  white-space: nowrap;
}

.gap-fun__pct {
  text-align: right;
  font-size: 13px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $p-ink-3;
}


/* ---------- by program ---------- */

.gap-progs {
  display: grid;
  gap: 16px;
}

.gap-prog { min-width: 0; }

.gap-prog__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 8px;
}

.gap-prog__name {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: $p-navy;
}

.gap-prog__count {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $p-ink-3;
}

.gap-prog__track {
  display: block;
  height: 6px;
  border-radius: 999px;
  background: $p-tint;
  overflow: hidden;
}

.gap-prog__fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: $p-blue;
  transform-origin: left center;
}

/* later rows step back, so the ranking reads without needing
   a second colour */
.gap-prog--2 .gap-prog__fill { background: rgba(21, 96, 224, 0.72); }
.gap-prog--3 .gap-prog__fill { background: rgba(21, 96, 224, 0.55); }
.gap-prog--4 .gap-prog__fill { background: rgba(21, 96, 224, 0.42); }
.gap-prog--5 .gap-prog__fill { background: rgba(21, 96, 224, 0.32); }
.gap-prog--6 .gap-prog__fill { background: rgba(21, 96, 224, 0.24); }


/* =========================================================
   TABLE
   ========================================================= */

.gap-block {
  border: 1px solid $p-line;
  border-radius: 16px;
  background: $p-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
}

.gap-block__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px 24px;
  padding: 22px 24px 20px;
}

.gap .gap-block__title {
  margin: 0;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.018em;
  color: $p-navy;
}

.gap .gap-block__hint {
  margin: 4px 0 0;
  font-size: 12.5px;
  color: $p-ink-4;
}

/* tabs read through weight and a quiet surface, not by flooding
   the control with the accent */
.gap-tabs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
  padding: 4px;
  border: 1px solid $p-line;
  border-radius: 11px;
  background: $p-page;
}

.gap-tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 13px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: $p-ink-3;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: background 0.4s $p-ease, color 0.4s $p-ease, border-color 0.4s $p-ease;
}

.gap-tab:hover { color: $p-navy; }

.gap-tab.is-on {
  background: $p-white;
  border-color: $p-line;
  color: $p-navy;
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.06);
}

.gap-tab__count {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: $p-ink-4;
}

.gap-table { min-width: 0; }

/* Column alignment.

   The amount is right aligned so the figures stack on their
   last digit, which is the only way a column of money is
   readable. The stage is left aligned so every track starts at
   the same x. Between them sits a wide gap, because a right
   aligned column running straight into a left aligned one gives
   you a ragged seam that reads as one broken column.

   Both header labels use the same alignment as the cells under
   them, which is what was actually wrong before. */
.gap-table__head,
.gap-row {
  display: grid;
  grid-template-columns: 128px minmax(0, 1fr) 118px 132px 210px 104px;
  align-items: center;
  gap: 0 26px;
  padding: 0 24px;
}

/* The amount column, hard right on both rows.

   Grid gap is uniform across every column, so widening it to
   separate these two would also push Reference away from
   Program, where the space is not wanted. The separation is
   added as padding on the two columns that need it instead:
   a little on the right of the amount, more on the left of the
   stage, which comes to roughly 60px between the last digit
   and the first segment of the track. */
.gap-table__head > :nth-child(4),
.gap-row > :nth-child(4) {
  text-align: right;
  justify-self: stretch;
  padding-right: 10px;
}

/* the stage column, hard left on both rows, pushed clear of the
   figures beside it */
.gap-table__head > :nth-child(5),
.gap-row > :nth-child(5) {
  text-align: left;
  justify-self: start;
  padding-left: 24px;
}

/* the action column, hard right on both rows */
.gap-table__head > :nth-child(6),
.gap-row > :nth-child(6) {
  text-align: right;
  justify-self: end;
}

.gap-table__head {
  height: 42px;
  border-top: 1px solid $p-line-2;
  border-bottom: 1px solid $p-line-2;
  background: rgba(10, 37, 64, 0.015);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: $p-ink-4;
}

.gap-row {
  min-height: 66px;
  padding-top: 14px;
  padding-bottom: 14px;
  border-bottom: 1px solid $p-line-2;
  transition: background 0.4s $p-ease;
}

.gap-row:last-child { border-bottom: 0; }

.gap-row:hover { background: rgba(21, 96, 224, 0.025); }

.gap-cell {
  min-width: 0;
  font-size: 14px;
  color: $p-ink-2;
}

.gap-cell--ref {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.004em;
  color: $p-navy;
}

.gap-cell--prog { display: flex; flex-direction: column; gap: 3px; }

.gap-cell__name {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: $p-navy;
}

.gap-cell__sub {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 12.5px;
  color: $p-ink-4;
}

.gap-cell--date,
.gap-cell--num {
  font-variant-numeric: tabular-nums;
}

.gap-cell--num {
  font-size: 14px;
  font-weight: 600;
  color: $p-navy;
  white-space: nowrap;
}

/* said rather than left blank, so nobody wonders whether the
   date failed to load */
.gap-cell.is-blank {
  font-style: italic;
  color: $p-ink-4;
}


/* ---------- the micro track ---------- */

/* fixed track width plus a fixed gap means every stage label
   begins at the same x down the column */
/* fixed track width plus a fixed gap means every stage label
   begins at the same x down the column */
.gap-cell--stage {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

/* a hairline where the right aligned column meets the left
   aligned one, so the seam reads as a boundary rather than as
   two columns that drifted together */
.gap-row > .gap-cell--stage::before {
  content: "";
  position: absolute;
  top: -14px;
  bottom: -14px;
  left: -12px;
  width: 1px;
  background: $p-line-2;
}

.gap-mini {
  display: flex;
  gap: 3px;
  flex-shrink: 0;
  width: 64px;
}

.gap-mini__seg {
  flex: 1;
  height: 5px;
  border-radius: 999px;
  background: $p-line-2;
}

.gap-mini__seg.is-done { background: rgba(21, 96, 224, 0.35); }
.gap-mini__seg.is-now  { background: $p-blue; }

/* a journey that stopped is not a journey in progress */
.gap-mini.is-stopped .gap-mini__seg { background: rgba(10, 37, 64, 0.14); }

.gap-mini__label {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 13px;
  font-weight: 500;
  color: $p-ink-2;
}

.gap-row--awarded .gap-mini__label { color: $p-good; font-weight: 600; }
.gap-row--closed .gap-mini__label  { color: $p-ink-4; }
.gap-row--new .gap-mini__label     { color: $p-warn; font-weight: 600; }


/* =========================================================
   BUTTONS
   ========================================================= */

.gap-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 36px;
  padding: 0 16px;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.4s $p-ease, border-color 0.4s $p-ease, color 0.4s $p-ease;
}

.gap-btn--primary {
  background: $p-blue;
  border-color: $p-blue;
  color: $p-white;
}

.gap-btn--primary:hover,
.gap-btn--primary:focus {
  background: $p-blue-dk;
  border-color: $p-blue-dk;
  color: $p-white;
  text-decoration: none;
}

.gap-btn--ghost {
  border-color: $p-line;
  color: $p-ink-2;
}

.gap-btn--ghost:hover,
.gap-btn--ghost:focus {
  border-color: $p-blue-2;
  color: $p-blue-dk;
  text-decoration: none;
}

.gap-btn:focus-visible,
.gap-tab:focus-visible,
.gap-search__clear:focus-visible {
  outline: 2px solid $p-blue;
  outline-offset: 2px;
}


/* =========================================================
   EMPTY AND PAGER
   ========================================================= */

.gap-blank,
.gap-nomatch {
  padding: 62px 24px;
  text-align: center;
}

.gap-blank__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 54px;
  height: 54px;
  margin: 0 auto 18px;
  border-radius: 50%;
  background: $p-blue-1;
  color: $p-blue;
  font-size: 20px;
}

.gap .gap-blank__title,
.gap .gap-nomatch__title {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.018em;
  color: $p-navy;
}

.gap .gap-blank__text,
.gap .gap-nomatch__text {
  max-width: 46ch;
  margin: 9px auto 20px;
  font-size: 14.5px;
  line-height: 1.6;
  color: $p-ink-3;
}

.gap-pager {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 20px 24px 24px;
}

.gap-pager__nums {
  display: flex;
  align-items: center;
  gap: 2px;
}

.gap-pager__step,
.gap-pager__num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 34px;
  height: 34px;
  padding: 0 6px;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: $p-ink-2;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition: background 0.4s $p-ease, border-color 0.4s $p-ease, color 0.4s $p-ease;
}

.gap-pager__step { border-color: $p-line; }

.gap-pager__step:hover:not(:disabled),
.gap-pager__num:hover:not(:disabled) {
  background: $p-tint;
  color: $p-navy;
}

.gap-pager__step:disabled {
  color: rgba(10, 37, 64, 0.22);
  cursor: default;
}

.gap-pager__num.is-on {
  background: $p-blue;
  border-color: $p-blue;
  color: $p-white;
  font-weight: 600;
}

.gap-pager__num.is-gap {
  min-width: 20px;
  color: $p-ink-4;
  cursor: default;
  pointer-events: none;
}


/* =========================================================
   DETAIL MODAL
   Read only. Everything the applicant submitted, grouped the
   way the form asked for it, so the two are recognisable as
   the same thing.
   ========================================================= */

.gap-modal {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1050;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 44px 20px;
  overflow-y: auto;
  background: rgba(10, 37, 64, 0.42);
  -webkit-backdrop-filter: blur(3px);
  backdrop-filter: blur(3px);
}

.gap-modal__panel {
  width: 100%;
  max-width: 820px;
  border-radius: 18px;
  background: $p-white;
  box-shadow: 0 30px 80px rgba(10, 37, 64, 0.3);
  overflow: hidden;
}

.gap-modal__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 24px 26px 20px;
  border-bottom: 1px solid $p-line-2;
}

.gap-modal__lead { min-width: 0; }

.gap-modal__ref {
  display: block;
  margin-bottom: 7px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: $p-ink-4;
}

.gap .gap-modal__title {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
  line-height: 1.24;
  letter-spacing: -0.026em;
  color: $p-navy;
}

.gap-modal__stage {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 11px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.gap-modal__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.gap-modal__stage--new     { color: $p-warn; }
.gap-modal__stage--review  { color: $p-blue-dk; }
.gap-modal__stage--awarded { color: $p-good; }
.gap-modal__stage--closed  { color: $p-ink-4; }

.gap-modal__stage--new .gap-modal__dot     { background: $p-warn; }
.gap-modal__stage--review .gap-modal__dot  { background: $p-blue; }
.gap-modal__stage--awarded .gap-modal__dot { background: $p-good; }
.gap-modal__stage--closed .gap-modal__dot  {
  background: transparent;
  box-shadow: inset 0 0 0 1.5px rgba(10, 37, 64, 0.28);
}

.gap-modal__x {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border: 1px solid $p-line;
  border-radius: 10px;
  background: transparent;
  color: $p-ink-3;
  font-size: 13px;
  cursor: pointer;
  transition: border-color 0.4s $p-ease, color 0.4s $p-ease;
}

.gap-modal__x:hover {
  border-color: $p-blue-2;
  color: $p-blue-dk;
}

.gap-modal__body {
  max-height: 62vh;
  padding: 4px 26px 20px;
  overflow-y: auto;
}

.gap-sec {
  padding: 22px 0;
  border-bottom: 1px solid $p-line-2;
}

.gap-sec:last-child { border-bottom: 0; }

.gap .gap-sec__title {
  margin: 0 0 14px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $p-blue;
}

.gap .gap-sec__rows {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 32px;
  margin: 0;
  padding: 0;
}

.gap-kv { min-width: 0; }

.gap .gap-kv dt {
  margin: 0 0 3px;
  font-size: 12px;
  color: $p-ink-4;
}

.gap .gap-kv dd {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.5;
  letter-spacing: -0.008em;
  color: $p-navy;
  word-break: break-word;
}

.gap .gap-kv dd.gap-kv--num { font-variant-numeric: tabular-nums; }

/* said rather than left blank, so nobody wonders whether it
   failed to load or was never filled in */
.gap .gap-kv dd.is-blank {
  font-weight: 400;
  font-style: italic;
  color: $p-ink-4;
}

.gap-prose { margin-top: 18px; }

.gap .gap-prose__label {
  margin: 0 0 6px;
  font-size: 12px;
  color: $p-ink-4;
}

/* the line breaks the applicant typed are kept, since a
   proposal written in paragraphs should read as paragraphs */
.gap .gap-prose__text {
  margin: 0;
  max-width: 72ch;
  font-size: 14.5px;
  line-height: 1.7;
  color: $p-ink-2;
  white-space: pre-line;
}

.gap-modal__foot {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 16px 26px;
  border-top: 1px solid $p-line-2;
  background: $p-page;
}

@media (max-width: 720px) {

  .gap-modal { padding: 20px 12px; }

  .gap-modal__panel { border-radius: 14px; }

  .gap-modal__head { padding: 20px 18px 16px; }
  .gap-modal__body { padding: 4px 18px 16px; max-height: 68vh; }
  .gap-modal__foot { padding: 14px 18px; }

  .gap .gap-sec__rows { grid-template-columns: minmax(0, 1fr); }

  .gap .gap-modal__title { font-size: 19px; }
}


/* =========================================================
   MOTION
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gapRise {
    from { opacity: 0; transform: translateY(14px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  @keyframes gapDrawX {
    from { transform: scaleX(0); }
    to   { transform: scaleX(1); }
  }

  .gap-top   { animation: gapRise 0.6s $p-ease backwards; }
  .gap-tile  { animation: gapRise 0.62s $p-ease backwards; }

  .gap-tile--total  { animation-delay: 0.06s; }
  .gap-tile--review { animation-delay: 0.12s; }
  .gap-tile--rate   { animation-delay: 0.18s; }
  .gap-tile--value  { animation-delay: 0.24s; }

  .gap-tile__rule { animation: gapDrawX 0.7s $p-ease 0.3s backwards; }

  .gap-panel { animation: gapRise 0.62s $p-ease 0.28s backwards; }
  .gap-block { animation: gapRise 0.62s $p-ease 0.34s backwards; }

  /* the bars grow from their own axis, staggered down each panel */
  .gap-fun__fill { animation: gapDrawX 0.8s $p-ease backwards; }

  .gap-fun--submitted .gap-fun__fill { animation-delay: 0.40s; }
  .gap-fun--reviewed .gap-fun__fill  { animation-delay: 0.47s; }
  .gap-fun--declined .gap-fun__fill  { animation-delay: 0.54s; }
  .gap-fun--awarded .gap-fun__fill   { animation-delay: 0.61s; }

  .gap-prog__fill { animation: gapDrawX 0.8s $p-ease backwards; }

  .gap-prog--1 .gap-prog__fill { animation-delay: 0.42s; }
  .gap-prog--2 .gap-prog__fill { animation-delay: 0.48s; }
  .gap-prog--3 .gap-prog__fill { animation-delay: 0.54s; }
  .gap-prog--4 .gap-prog__fill { animation-delay: 0.60s; }
  .gap-prog--5 .gap-prog__fill { animation-delay: 0.66s; }
  .gap-prog--6 .gap-prog__fill { animation-delay: 0.72s; }

  /* replays on every tab change, because ng-repeat rebuilds its
     nodes and the keyframe starts again with them */
  .gap-row { animation: gapRise 0.45s $p-ease backwards; }

  .gap-row--n1  { animation-delay: 0.02s; }
  .gap-row--n2  { animation-delay: 0.05s; }
  .gap-row--n3  { animation-delay: 0.08s; }
  .gap-row--n4  { animation-delay: 0.11s; }
  .gap-row--n5  { animation-delay: 0.14s; }
  .gap-row--n6  { animation-delay: 0.17s; }
  .gap-row--n7  { animation-delay: 0.20s; }
  .gap-row--n8  { animation-delay: 0.23s; }
  .gap-row--n9  { animation-delay: 0.26s; }
  .gap-row--n10 { animation-delay: 0.29s; }

  @keyframes gapModalIn {
    from { opacity: 0; transform: translateY(16px) scale(0.99); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
  }

  @keyframes gapVeilIn {
    from { opacity: 0; }
    to   { opacity: 1; }
  }

  .gap-modal { animation: gapVeilIn 0.28s $p-ease backwards; }
  .gap-modal__panel { animation: gapModalIn 0.4s $p-ease 0.04s backwards; }
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1360px) {

  .gap { padding: 26px 24px 60px; }

  .gap-table__head,
  .gap-row {
    grid-template-columns: 116px minmax(0, 1fr) 104px 112px 178px 100px;
    gap: 0 18px;
    padding: 0 18px;
  }

  .gap-table__head > :nth-child(5),
  .gap-row > :nth-child(5) { padding-left: 18px; }
}

@media (max-width: 1150px) {

  .gap-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }

  .gap-panels { grid-template-columns: minmax(0, 1fr); }

  /* the table stops being a table, because six columns at this
     width means four of them are two characters wide */
  .gap-table__head { display: none; }

  .gap-row {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 14px;
    padding: 16px 18px;
  }

  .gap-cell--prog { grid-column: 1 / -1; }

  .gap-cell::before {
    content: attr(data-label);
    display: block;
    margin-bottom: 4px;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: $p-ink-4;
  }

  .gap-cell--prog::before { display: none; }

  .gap-right { text-align: left; }

  .gap-cell--stage {
    flex-direction: column;
    align-items: flex-start;
    gap: 7px;
  }

  /* stacked rows have no columns to divide */
  .gap-row > .gap-cell--stage::before { display: none; }

  .gap-table__head > :nth-child(4),
  .gap-row > :nth-child(4) { padding-right: 0; }

  .gap-table__head > :nth-child(5),
  .gap-row > :nth-child(5) { padding-left: 0; }
}

@media (max-width: 820px) {

  .gap { padding: 22px 16px 52px; }

  .gap-top__right {
    width: 100%;
    order: 2;
  }

  .gap-search { width: 100%; }

  .gap-tiles { grid-template-columns: minmax(0, 1fr); }

  .gap-block__head { align-items: stretch; flex-direction: column; }

  .gap-tabs {
    flex-wrap: nowrap;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .gap-tab { flex-shrink: 0; }

  .gap-row { grid-template-columns: minmax(0, 1fr); }

  .gap-fun { grid-template-columns: 84px minmax(0, 1fr) 40px; gap: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  .gap * { transition: none; }
  .gap-tile:hover { transform: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW · MY APPLICATIONS
     Service Portal widget · Server script

     Structure is the one on screen: four figures, a stage
     conversion panel, a by-program panel, then the table.
     Only the presentation changes.

     Three figures were saying things the data did not support,
     and those are fixed here:

       "Average 18 days in review" with nothing in review.
       The average is now only calculated from applications
       actually sitting in a review state, and the tile says so
       when there are none.

       "Success rate 0%" before any decision has come back.
       A rate over zero decided applications is not zero, it is
       undefined. It reads as a dash until something has been
       decided either way.

       "Across 2 programs, last 12 months" on a query with no
       date filter. The window is real now.

     GlideRecordSecure throughout.
     ========================================================= */

  var APPLICANT = 'x_enno_gatenow_service_applicants';

  var me = gs.getUserID();
  var MONTHS_BACK = 12;

  function opt(name, fallback) {
    var v = options[name];
    return (v === null || v === undefined || v === '') ? fallback : v.toString();
  }

  function lower(v) {
    return (v === null || v === undefined) ? '' : ('' + v).toLowerCase();
  }

  function toGDT(value) {
    if (!value) return null;
    var s = '' + value;
    if (s.length === 10) s += ' 00:00:00';
    try { return new GlideDateTime(s); } catch (e) { return null; }
  }

  function fmtDate(value) {
    var g = toGDT(value);
    if (!g) return '';
    try { return g.getDate().getByFormat('d MMM yyyy'); } catch (e) { return '' + value; }
  }

  function daysSince(value) {
    var g = toGDT(value);
    if (!g) return null;
    try {
      var ms = GlideDateTime.subtract(g, new GlideDateTime()).getNumericValue();
      return Math.round(ms / 86400000);
    } catch (e) { return null; }
  }

  function num(raw) {
    if (raw === null || raw === undefined || raw === '') return 0;
    var s = '' + raw;
    if (s.indexOf(';') !== -1) s = s.split(';').pop();
    var n = parseFloat(s);
    return isNaN(n) ? 0 : n;
  }

  /* written out rather than toLocaleString, which is not
     dependable on the server engine */
  function commas(n) {
    var s = '' + Math.round(n);
    var out = '';
    var c = 0;
    for (var i = s.length - 1; i >= 0; i--) {
      out = s.charAt(i) + out;
      c++;
      if (c % 3 === 0 && i > 0) out = ',' + out;
    }
    return out;
  }

  function fmtShort(n) {
    if (!n) return '$0';
    if (n >= 1000000) return '$' + (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'M';
    if (n >= 1000)    return '$' + Math.round(n / 1000) + 'K';
    return '$' + commas(n);
  }

  function pick(gr, names) {
    for (var i = 0; i < names.length; i++) {
      try {
        if (gr.isValidField(names[i])) {
          var v = gr.getValue(names[i]);
          if (v !== null && v !== undefined && v !== '') return v;
        }
      } catch (e) { /* next */ }
    }
    return '';
  }


  /* ---------- chrome ---------- */
  data.sideBar = $sp.getWidget(opt('sidebar_widget', 'sidebar'));

  var u = gs.getUser();
  var fn = u.getFirstName() || '';
  var ln = u.getLastName() || '';
  data.userInitials = (fn.charAt(0) + ln.charAt(0)).toUpperCase() ||
                      (u.getDisplayName() || 'U').substring(0, 2).toUpperCase();

  data.pages = {
    intake  : opt('intake_page', 'applicant_intake'),
    programs: opt('programs_page', 'x_enno_gatenow_programs'),
    awards  : opt('awards_page', 'x_enno_gatenow_awards'),
    detail  : opt('detail_page', 'x_enno_gatenow_application')
  };


  /* ============================================================
     STATE MAP
     stage drives the micro track in the table.
     group drives the tabs.
     ============================================================ */

  var STATES = {
    /* new means submitted and not yet picked up, not a draft.
       These records already carry a submission date, so the row
       action is View rather than Resume. */
    'new':                   { group: 'new',     stage: 1, label: gs.getMessage('New') },
    'ready_for_review':      { group: 'review',  stage: 1, label: gs.getMessage('Submitted') },
    'review_in_progress':    { group: 'review',  stage: 2, label: gs.getMessage('Under review') },
    'review_completed':      { group: 'review',  stage: 2, label: gs.getMessage('Reviewed') },
    'award_pending':         { group: 'awarded', stage: 3, label: gs.getMessage('Award offered') },
    'award_acknowledged':    { group: 'awarded', stage: 3, label: gs.getMessage('Awarded') },
    'project_in_progress':   { group: 'awarded', stage: 3, label: gs.getMessage('In delivery') },
    'project_completed':     { group: 'awarded', stage: 3, label: gs.getMessage('Completed') },
    'declined_by_agency':    { group: 'closed',  stage: 3, label: gs.getMessage('Not selected') },
    'declined_by_applicant': { group: 'closed',  stage: 3, label: gs.getMessage('You declined') },
    'cancelled':             { group: 'closed',  stage: 3, label: gs.getMessage('Cancelled') }
  };


  /* ============================================================
     RECORDS
     ============================================================ */

  data.applications = [];

  var counts = { all: 0, new: 0, review: 0, awarded: 0, closed: 0 };

  var requested = 0;
  var awardedValue = 0;
  var reviewDays = [];
  var byProgram = {};

  /* the funnel counts every application that reached a stage,
     not only the ones sitting in it now */
  var funnel = { submitted: 0, reviewed: 0, declined: 0, awarded: 0 };

  var since = new GlideDateTime();
  since.addMonthsLocalTime(-MONTHS_BACK);

  try {

    var gr = new GlideRecordSecure(APPLICANT);
    gr.addQuery('user', me);
    gr.addQuery('sys_created_on', '>=', since.getValue());
    gr.orderByDesc('sys_updated_on');
    gr.setLimit(300);
    gr.query();

    while (gr.next()) {

      var stateVal = lower(gr.getValue('state'));
      var meta = STATES[stateVal] || {
        group: 'review', stage: 1,
        label: gr.getDisplayValue('state') || gs.getMessage('In progress')
      };

      var asked   = num(pick(gr, ['requested_budget']));
      var program = gr.getDisplayValue('program') || gs.getMessage('Unassigned');
      var subRaw  = gr.getValue('submission_date');

      /* Everything the modal shows is loaded here rather than
         fetched on open. A second server call would re-run this
         script and repaint the widget, which is the flicker we
         removed from the intake form. */
      data.applications.push({
        sysId     : gr.getUniqueValue(),
        number    : gr.getValue('number'),
        program   : program,
        programId : gr.getValue('program'),
        category  : gr.getValue('program_category') || gr.getDisplayValue('category'),
        title     : pick(gr, ['proposal_title', 'short_description']),
        group     : meta.group,
        stage     : meta.stage,
        stateLabel: meta.label,
        amount    : asked,
        amountText: asked ? fmtShort(asked) : '',
        amountFull: asked ? '$' + commas(asked) : '',
        submitted : subRaw ? fmtDate(subRaw) : '',
        updated   : fmtDate(gr.getValue('sys_updated_on')),

        detail: {
          applicant   : [pick(gr, ['first_name']), pick(gr, ['middle_name']), pick(gr, ['last_name'])]
                          .filter(function (x) { return !!x; }).join(' '),
          email       : pick(gr, ['email']),
          phone       : pick(gr, ['phone_number']),
          address     : [pick(gr, ['street']), pick(gr, ['city']),
                         pick(gr, ['zip_postal_code']), pick(gr, ['country'])]
                          .filter(function (x) { return !!x; }).join(', '),
          organisation: pick(gr, ['organization']),
          applicantType: gr.getDisplayValue('applicant_type'),
          identityType: gr.getDisplayValue('identity_type'),
          uei         : pick(gr, ['uei']),
          tin         : pick(gr, ['tin_ein']),
          citizenship : gr.getDisplayValue('citizenship_status'),
          birthdate   : fmtDate(gr.getValue('birthdate')),

          /* Deliberately not published: ssn.

             It is on the record and it would be trivial to add
             here, but this payload is readable in the browser on
             a page whose only job is to remind someone what they
             already typed. There is no reason to put a social
             security number back on screen for that. If a caller
             genuinely needs it, they need the record, not this
             widget. */

          gender      : gr.getDisplayValue('gender'),
          race        : gr.getDisplayValue('race'),
          ethnicity   : gr.getDisplayValue('ethnicity'),
          education   : gr.getDisplayValue('education_level'),
          marital     : gr.getDisplayValue('marital_status'),
          military    : gr.getDisplayValue('military_status'),
          disability  : gr.getDisplayValue('disability_status'),
          tribal      : gr.getDisplayValue('tribal_affiliation'),

          proposalTitle: pick(gr, ['proposal_title']),
          summary      : pick(gr, ['short_description']),
          description  : pick(gr, ['proposal_description']),
          goals        : pick(gr, ['project_goals_and_objectives']),
          method       : pick(gr, ['project_activities_methodology']),
          startDate    : fmtDate(gr.getValue('project_start_date')),
          endDate      : fmtDate(gr.getValue('project_end_date')),
          files        : 0
        }
      });

      counts.all++;
      counts[meta.group]++;
      requested += asked;

      byProgram[program] = (byProgram[program] || 0) + 1;

      /* funnel: reaching a later stage implies the earlier ones */
      if (meta.stage >= 1) funnel.submitted++;
      if (meta.stage >= 2) funnel.reviewed++;
      if (meta.group === 'awarded') { funnel.awarded++; awardedValue += asked; }
      if (meta.group === 'closed')  funnel.declined++;

      /* only applications genuinely in review contribute to the
         average time in review */
      if (meta.group === 'review' && subRaw) {
        var d = daysSince(subRaw);
        if (d !== null && d >= 0) reviewDays.push(d);
      }
    }

  } catch (e) {
    gs.error('[MyApplications] ' + e.message);
  }

  /* One aggregate for every attachment count, rather than a
     query per row. Three hundred rows would otherwise be three
     hundred queries. */
  try {
    if (data.applications.length) {

      var ids = [];
      for (var k = 0; k < data.applications.length; k++) {
        ids.push(data.applications[k].sysId);
      }

      var byId = {};
      var ag = new GlideAggregate('sys_attachment');
      ag.addQuery('table_name', APPLICANT);
      ag.addQuery('table_sys_id', 'IN', ids.join(','));
      ag.addAggregate('COUNT', 'table_sys_id');
      ag.groupBy('table_sys_id');
      ag.query();

      while (ag.next()) {
        byId[ag.getValue('table_sys_id')] = parseInt(ag.getAggregate('COUNT', 'table_sys_id'), 10) || 0;
      }

      for (var m = 0; m < data.applications.length; m++) {
        data.applications[m].detail.files = byId[data.applications[m].sysId] || 0;
      }
    }
  } catch (e) {
    gs.info('[MyApplications] attachment count unavailable: ' + e.message);
  }

  data.counts = counts;


  /* ---------- header line ---------- */
  data.headline = counts.all + ' ' +
    (counts.all === 1 ? gs.getMessage('application') : gs.getMessage('applications')) +
    '  ·  ' + counts.review + ' ' + gs.getMessage('currently under review');


  /* ---------- four figures ---------- */

  var avgReview = 0;
  if (reviewDays.length) {
    var total = 0;
    for (var i = 0; i < reviewDays.length; i++) total += reviewDays[i];
    avgReview = Math.round(total / reviewDays.length);
  }

  var decided = counts.awarded + counts.closed;

  data.tiles = [
    {
      key  : 'total',
      label: gs.getMessage('Total applications'),
      value: '' + counts.all,
      note : Object.keys(byProgram).length + ' ' +
             (Object.keys(byProgram).length === 1 ? gs.getMessage('program') : gs.getMessage('programs')) +
             ', ' + gs.getMessage('last 12 months')
    },
    {
      key  : 'review',
      label: gs.getMessage('Under review'),
      value: '' + counts.review,
      /* an average over nothing is not a number */
      note : reviewDays.length
               ? gs.getMessage('average') + ' ' + avgReview + ' ' + gs.getMessage('days waiting')
               : gs.getMessage('nothing with the review team')
    },
    {
      key  : 'rate',
      /* a rate over zero decisions is undefined, not zero */
      label: gs.getMessage('Success rate'),
      value: decided ? Math.round((counts.awarded / decided) * 100) + '%' : '—',
      note : decided
               ? counts.awarded + ' ' + gs.getMessage('awarded of') + ' ' + decided + ' ' + gs.getMessage('decided')
               : gs.getMessage('no decisions returned yet')
    },
    {
      key  : 'value',
      label: gs.getMessage('Value requested'),
      value: fmtShort(requested),
      note : fmtShort(awardedValue) + ' ' + gs.getMessage('awarded to date')
    }
  ];


  /* ---------- stage conversion ---------- */

  var base = funnel.submitted || 0;

  function stageRow(key, label, count) {
    return {
      key  : key,
      label: label,
      count: count,
      pct  : base ? Math.round((count / base) * 100) : 0,
      /* a bar of zero still needs to be visible as a track */
      width: base ? Math.max(count > 0 ? 4 : 0, Math.round((count / base) * 100)) : 0
    };
  }

  data.funnel = [
    stageRow('submitted', gs.getMessage('Submitted'), funnel.submitted),
    stageRow('reviewed',  gs.getMessage('Reviewed'),  funnel.reviewed),
    stageRow('declined',  gs.getMessage('Declined'),  funnel.declined),
    stageRow('awarded',   gs.getMessage('Awarded'),   funnel.awarded)
  ];


  /* ---------- by program ---------- */

  var rows = [];
  for (var name in byProgram) {
    rows.push({ label: name, count: byProgram[name] });
  }
  rows.sort(function (a, b) { return b.count - a.count; });

  var top = rows.length ? rows[0].count : 0;

  data.byProgram = [];
  for (var r = 0; r < rows.length && r < 6; r++) {
    data.byProgram.push({
      label: rows[r].label,
      count: rows[r].count,
      width: top ? Math.max(6, Math.round((rows[r].count / top) * 100)) : 0
    });
  }


  /* ---------- micro track labels ---------- */
  data.track = [
    gs.getMessage('New'),
    gs.getMessage('Submitted'),
    gs.getMessage('Review'),
    gs.getMessage('Decision')
  ];


  /* ============================================================
     COPY
     ============================================================ */

  data.t = {
    title    : opt('label_title', gs.getMessage('My applications')),
    search   : gs.getMessage('Search programs, applications...'),

    funnelTitle: gs.getMessage('Stage conversion'),
    funnelHint : gs.getMessage('How your applications move through the lifecycle'),
    funnelFoot : gs.getMessage('Counts are applications that reached each stage. Percentages are of everything submitted.'),

    progTitle: gs.getMessage('Applications by program'),
    progHint : gs.getMessage('Where you have applied most'),
    progEmpty: gs.getMessage('Nothing to chart yet.'),

    listTitle: gs.getMessage('All applications'),
    listHint : gs.getMessage('Sorted by last update'),

    colRef    : gs.getMessage('Reference'),
    colProgram: gs.getMessage('Program'),
    colSub    : gs.getMessage('Submitted'),
    colReq    : gs.getMessage('Requested'),
    colStage  : gs.getMessage('Stage'),
    colAction : gs.getMessage('Action'),

    tabAll    : gs.getMessage('All'),
    tabNew    : gs.getMessage('New'),
    tabReview : gs.getMessage('In review'),
    tabAwarded: gs.getMessage('Awarded'),
    tabClosed : gs.getMessage('Closed'),

    view     : gs.getMessage('View'),
    notSent  : gs.getMessage('Not submitted'),

    mClose      : gs.getMessage('Close'),
    mRequest    : gs.getMessage('The request'),
    mApplicant  : gs.getMessage('Applicant'),
    mProposal   : gs.getMessage('The proposal'),
    mProgram    : gs.getMessage('Program'),
    mCategory   : gs.getMessage('Category'),
    mReference  : gs.getMessage('Reference'),
    mStage      : gs.getMessage('Stage'),
    mRequested  : gs.getMessage('Requested'),
    mSubmitted  : gs.getMessage('Submitted'),
    mUpdated    : gs.getMessage('Last change'),
    mName       : gs.getMessage('Name'),
    mEmail      : gs.getMessage('Email'),
    mPhone      : gs.getMessage('Phone'),
    mAddress    : gs.getMessage('Address'),
    mOrg        : gs.getMessage('Organisation'),
    mType       : gs.getMessage('Applicant type'),
    mIdentity   : gs.getMessage('Identity type'),
    mUei        : gs.getMessage('UEI'),
    mTin        : gs.getMessage('TIN or EIN'),
    mCitizen    : gs.getMessage('Citizenship'),
    mTitle      : gs.getMessage('Title'),
    mSummary    : gs.getMessage('One line summary'),
    mDescription: gs.getMessage('Description'),
    mGoals      : gs.getMessage('Goals and objectives'),
    mMethod     : gs.getMessage('Activities and methodology'),
    mDates      : gs.getMessage('Project dates'),
    mTo         : gs.getMessage('to'),
    mFiles      : gs.getMessage('Documents attached'),
    mNone       : gs.getMessage('Not provided'),

    mBackground : gs.getMessage('Background'),
    mBirthdate  : gs.getMessage('Date of birth'),
    mGender     : gs.getMessage('Gender'),
    mRace       : gs.getMessage('Race'),
    mEthnicity  : gs.getMessage('Ethnicity'),
    mEducation  : gs.getMessage('Education level'),
    mMarital    : gs.getMessage('Marital status'),
    mMilitary   : gs.getMessage('Military status'),
    mDisability : gs.getMessage('Disability status'),
    mTribal     : gs.getMessage('Tribal affiliation'),

    emptyTitle: gs.getMessage('No applications yet'),
    emptyText : gs.getMessage('Apply to a program and it appears here, from first draft through to a decision.'),
    emptyBtn  : gs.getMessage('Browse open programs'),

    noMatch    : gs.getMessage('Nothing matches this filter'),
    noMatchText: gs.getMessage('Try another tab, or clear the search.'),
    clear      : gs.getMessage('Clear')
  };

  data.pageSize = parseInt(opt('page_size', '10'), 10) || 10;

})();
